/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
}

export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(memberId?: MemberId) {
    super(memberId ? `Member ${memberId} is suspended` : "Member is suspended");
    this.name = "MemberSuspendedError";
  }
}

export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return setSuspension(actor, input, "suspended");
}

export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return setSuspension(actor, input, "active");
}

async function setSuspension(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
  status: "active" | "suspended",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const member = requireFound(
    await memberRepo.findMember(input.orgId, actor.userId).then(async () =>
      memberRepo.findMemberById(input.orgId, input.memberId),
    ),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot manage a ${member.role}`);
  }

  const nextStatus = status;
  if (member.status === nextStatus) return member;

  if (status === "suspended") {
    await assertLastOwnerRetained(input.orgId, input.memberId, "member");
  }

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    nextStatus,
  );
  await emit(status === "suspended" ? "member.suspended" : "member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });
  return updated;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

